// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.prank(nonOwner);
        bool reverts;
        try c.owned() { reverts = false; } catch { reverts = true; }
        assertTrue(reverts);
    }
}
